"""Generates migrations/028_egypt_places_and_subspecialties.sql from egypt_places.py (run once)."""
import re, sys, os
sys.path.insert(0, os.path.dirname(__file__))
from egypt_places import GOVERNORATES, SUBSPECIALTIES, EXISTING_ALEX

def slugify(s):
    return re.sub(r'-+', '-', re.sub(r'[^a-z0-9]+', '-', s.lower())).strip('-')

def q(s):
    assert "'" not in s or True
    return "'" + s.replace("'", "''") + "'"

used = set(EXISTING_ALEX)
out = ["""-- All of Egypt: 27 governorates with their main cities / districts, and many more subspecialties.
-- Generated by scripts/data/gen_places.py from scripts/data/egypt_places.py.
-- District slugs become unique across the country (they are used alone in search links).

alter table governorates add column sort smallint not null default 100;
"""]
for slug, en, ar, sort, _ in GOVERNORATES:
    out.append(f"insert into governorates (slug, name_en, name_ar, is_active, sort) values ({q(slug)}, {q(en)}, {q(ar)}, true, {sort})\n"
               f"  on conflict (slug) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, is_active = true, sort = excluded.sort;")
out.append("")
total = 0
for gslug, _, _, _, block in GOVERNORATES:
    rows = []
    seen_names = set()
    for line in block.strip().splitlines():
        en, ar = [x.strip() for x in line.split('|')]
        assert en and ar, line
        assert en.lower() not in seen_names, (gslug, en)
        seen_names.add(en.lower())
        s = slugify(en)
        if s in used:
            s = f"{gslug}-{s}"
        assert s not in used, s
        assert re.fullmatch(r'[a-z0-9-]+', s)
        used.add(s)
        rows.append(f"  ({q(s)}, {q(en)}, {q(ar)})")
    total += len(rows)
    out.append(f"insert into districts (governorate_id, slug, name_en, name_ar)\nselect g.id, d.slug, d.name_en, d.name_ar from governorates g, (values\n" + ",\n".join(rows) +
               f"\n) as d(slug, name_en, name_ar) where g.slug = {q(gslug)}\non conflict (governorate_id, slug) do nothing;\n")
out.append("create unique index districts_slug_unique_idx on districts(slug);\n")
nsub = 0
for spec, subs in SUBSPECIALTIES.items():
    slugs = [s for s, _, _ in subs]
    assert len(slugs) == len(set(slugs)), spec
    rows = ",\n".join(f"  ({q(s)}, {q(en)}, {q(ar)})" for s, en, ar in subs)
    nsub += len(subs)
    out.append(f"insert into subspecialties (specialty_id, slug, name_en, name_ar)\nselect s.id, x.slug, x.name_en, x.name_ar from specialties s, (values\n{rows}\n) as x(slug, name_en, name_ar) where s.slug = {q(spec)}\non conflict (specialty_id, slug) do nothing;\n")
open(os.path.join(os.path.dirname(__file__), '../../migrations/028_egypt_places_and_subspecialties.sql'), 'w').write("\n".join(out))
print('governorates', len(GOVERNORATES), 'new districts', total, 'subspecialties', nsub)
